#include <stdio.h>

int solution(int N, int M, int influencer[], int influencer_len) {
    int cities[101] = {0};
    for (int t = 0; t < M; t++) {
        int pos = influencer[t];
        int power = pos;
        for (int i = pos, p = power; i >= 1 && p > 0; i--, p--) {
            cities[i] += p;
        }
        for (int i = pos + 1, p = power - 1; i <= N && p > 0; i++, p--) {
            cities[i] += p;
        }
    }
    int total = 0;
    for (int i = 1; i <= N; i++) total += cities[i];
    return total;
}

